/** Replaced at build time by the cobalt-pwa plugin (tools/pwa/plugin.ts). */
declare const __SW_BUILD_ID__: string;
declare const __SW_PRECACHE__: string[];
/** File name of the page's entry chunk: proves a fetched index.html belongs to this build. */
declare const __SW_ENTRY__: string;
/** True for the kill-switch worker (VITE_SW=off), which removes itself and its caches. */
declare const __SW_KILL__: boolean;
